(()=>{
 const panel=document.createElement('details');panel.id='motion-path-panel';panel.className='advanced';panel.innerHTML='<summary>Emitter motion path</summary><p class="animation-intro">Move the starting point through a route. Select a waypoint below or drag its handle in the preview. Editing a route replaces X/Y/Z position keys; other property keys and particle events stay.</p>';
 const buttons=document.createElement('div');buttons.className='dynamics-recipes';panel.append(buttons);for(const [kind,title]of [['straight','Straight route'],['arc','Arc route'],['closed','Closed route']]){const button=document.createElement('button');button.id='path-'+kind;button.textContent=title;button.onclick=()=>{try{apply(EmberMotionPath.recipe(state,kind));}catch(error){toast(error.message);}};buttons.append(button);}
 const editLabel=document.createElement('label');editLabel.textContent='Drag waypoints in preview';const edit=document.createElement('input');edit.id='path-edit';edit.type='checkbox';editLabel.append(edit);panel.append(editLabel);
 const planeLabel=document.createElement('label');planeLabel.textContent='Drag plane';const plane=document.createElement('select');plane.id='path-plane';plane.setAttribute('aria-label','Waypoint drag plane');for(const [value,title]of [['XY','X/Y — left, right, forward, back'],['XZ','X/Z — left, right, up, down'],['YZ','Y/Z — forward, back, up, down']])plane.add(new Option(title,value));planeLabel.append(plane);panel.append(planeLabel);
 const status=document.createElement('p');status.className='animation-intro';status.id='path-status';panel.append(status);const host=document.createElement('div');host.id='path-points';panel.append(host);const add=document.createElement('button');add.id='path-add';add.textContent='Add waypoint after selected';panel.append(add);const clear=document.createElement('button');clear.id='path-clear';clear.textContent='Remove path, keep start';panel.append(clear);
 const hint=document.createElement('p');hint.className='animation-intro';hint.textContent='Coordinates are starting-position offsets in centimeters. Hold Shift while dragging to snap to 5 cm. Paths use straight segments, play once, then hold the last position. Restart replays them. Preset and aimed motion leave older particles behind; locked ring motion carries its orbit with the center.';panel.append(hint);$('#animation-panel').before(panel);
 let selected=0,drag=null;
 function apply(effect){Object.assign(state,effect);window.resetSelectedLayer?.();sync();persist();}
 function change(points){try{apply(EmberMotionPath.write(state,points));}catch(error){toast(error.message);refresh();}}
 edit.onchange=()=>{if(!edit.checked&&drag)finish(false);refresh();};plane.onchange=()=>{if(drag)finish(false);};
 add.onclick=()=>{const points=EmberMotionPath.read(state);if(points.length<2)return;const i=Math.min(selected,points.length-1),a=points[i],b=points[i+1],next=b?{time:(a.time+b.time)/2,x:(a.x+b.x)/2,y:(a.y+b.y)/2,z:(a.z+b.z)/2}:{time:Math.min(60,a.time+1),x:Math.min(10000,a.x+50),y:a.y,z:a.z};points.splice(i+1,0,next);selected=i+1;change(points);};
 clear.onclick=()=>{apply(EmberMotionPath.clear(state));edit.checked=false;refresh();};
 function refresh(){const points=EmberMotionPath.read(state);selected=Math.max(0,Math.min(selected,points.length-1));host.replaceChildren();edit.disabled=points.length<2||points.length>EmberMotionPath.capacity(state);plane.disabled=!edit.checked||edit.disabled;add.disabled=points.length<2||points.length>=EmberMotionPath.capacity(state)||selected===points.length-1&&points.at(-1).time>=60;clear.disabled=!points.length;status.textContent=points.length?points.length+' waypoints · '+points.at(-1).time.toFixed(2)+' seconds · '+(edit.checked?'Drag mode on':'Turn on drag mode to move handles'):'Choose a route to begin, or load Fireball path from Examples.';
  points.forEach((point,index)=>{const row=document.createElement('div');row.className='path-point'+(index===selected?' selected':'');const choose=document.createElement('button');choose.textContent='Waypoint '+(index+1);choose.onclick=()=>{selected=index;refresh();};row.append(choose);for(const [key,label,min,max]of [['time','Time (s)',index?points[index-1].time+.000001:0,index<points.length-1?points[index+1].time-.000001:60],['x','X',-10000,10000],['y','Y',-10000,10000],['z','Z',-10000,10000]]){const field=document.createElement('label');field.textContent=label;const input=document.createElement('input');input.type='number';input.step='any';input.min=min;input.max=max;input.value=point[key];input.disabled=key==='time'&&index===0;input.setAttribute('aria-label','Waypoint '+(index+1)+' '+label);input.onchange=()=>{if(!input.checkValidity()||!Number.isFinite(input.valueAsNumber)){refresh();return;}points[index][key]=input.valueAsNumber;selected=index;change(points);};field.append(input);row.append(field);}if(index>0&&points.length>2){const remove=document.createElement('button');remove.textContent='Remove';remove.onclick=()=>{points.splice(index,1);change(points);};row.append(remove);}host.append(row);});}
 function finish(commit){if(!drag)return;const before=drag;drag=null;if(!commit)Object.assign(state,before.effect);else{window.resetSelectedLayer?.();persist();}playing=before.playing;viewport.controls.enabled=before.controlsEnabled;sync();}
 window.emberPathEditor={get editing(){return edit.checked&&!edit.disabled;},get plane(){return plane.value;},get selected(){return selected;},effect:()=>state,time:()=>layers[activeLayer]?.time||0,select(index){selected=index;refresh();},begin(index){if(drag)return false;selected=index;drag={effect:structuredClone(state),points:EmberMotionPath.read(state),playing,controlsEnabled:viewport.controls.enabled,layer:activeLayer};playing=false;viewport.controls.enabled=false;refresh();return true;},move(position,snap){if(!drag||drag.layer!==activeLayer)return;const points=structuredClone(drag.points);for(const axis of ['x','y','z'])points[selected][axis]=Math.max(-10000,Math.min(10000,snap?Math.round(position[axis]/5)*5:position[axis]));try{Object.assign(state,EmberMotionPath.write(drag.effect,points));status.textContent='Waypoint '+(selected+1)+' · X '+points[selected].x.toFixed(1)+' · Y '+points[selected].y.toFixed(1)+' · Z '+points[selected].z.toFixed(1)+' cm';}catch(error){toast(error.message);}},finish};
 const previousRenderAnimation=renderAnimation;renderAnimation=()=>{previousRenderAnimation();if(!drag)refresh();};
 const previous=sync;sync=()=>{if(drag&&drag.layer!==activeLayer){playing=drag.playing;viewport.controls.enabled=drag.controlsEnabled;drag=null;}previous();refresh();};refresh();
})();
